# Writes the generated hedra command files of the lava forge's environment: island.txt (selection
# expressions for the pool, the channel and the cracks), lavafall.txt, embers.txt, blobs.txt.
# Run from models/env: /usr/bin/python3 make_env.py. Up Z, front -Y (hedra); colours exact Lava-GB.
import math, random

C = {"navy": (0.020, 0.122, 0.224), "purple": (0.290, 0.141, 0.502),
     "magenta": (0.773, 0.227, 0.616), "salmon": (1.0, 0.557, 0.502)}
def col(n, emit=False):
    r, g, b = C[n]
    s = f"--base-color {r:.3f} {g:.3f} {b:.3f}"
    return s + (f" --emission {r:.3f} {g:.3f} {b:.3f}" if emit else "")

def seg_expr(a, b, w):
    """faces whose centre lies within w of the segment a-b (top view)"""
    (ax, ay), (bx, by) = a, b
    dx, dy = bx - ax, by - ay
    L2 = dx * dx + dy * dy
    t = f"clamp(((pos.x - ({ax:.3f}))*({dx:.3f}) + (pos.y - ({ay:.3f}))*({dy:.3f})) / {L2:.4f}, 0, 1)"
    qx, qy = f"(({ax:.3f}) + {t}*({dx:.3f}))", f"(({ay:.3f}) + {t}*({dy:.3f}))"
    return f"(sqrt((pos.x - {qx})*(pos.x - {qx}) + (pos.y - {qy})*(pos.y - {qy})) < {w})"

R = 3.6                      # island radius (11-sided)
POOL = (1.4, -1.6)           # lava pool centre, radius 0.8
RIM = (2.263, -2.610)        # centre of side face 9 (normal at 310.9 degrees): where the lava falls
CRACKS = [  # polylines, top view, metres
    [(-0.6, -1.0), (-1.2, -1.6), (-1.5, -2.6)],
    [(0.5, -1.2), (0.2, -2.2), (0.6, -3.1)],
    [(-1.5, 0.0), (-2.4, 0.4), (-3.1, 0.2)],
    [(1.5, 0.3), (2.3, 0.6), (3.0, 1.4)],
    [(-1.0, 2.4), (-1.6, 2.6)],
    [(2.1, -1.0), (2.8, -0.6)],
]
FORGE_AREA = "(abs(pos.x) < 1.45 && pos.y > -0.75 && pos.y < 2.35) || (abs(pos.x + 1.6) < 0.45 && abs(pos.y + 0.05) < 0.45)"

isl = [f"""# Volcanic island: an 11-sided slab (top at z 0) whose top is fanned and subdivided into small
# triangles, so a lava pool, its channel to the rim and glowing cracks are picked as faces (no decals).
# A rocky underside cone. Generated by make_env.py. Up Z, front -Y.
new
material new Rock {col('navy')} --no-slot
material new Crack {col('magenta', True)} --no-slot
material new Lava {col('salmon', True)} --no-slot
add mesh cylinder --name Island --vertices 11 --radius {R} --depth 0.5 --location 0 0 -0.25
apply --location
material assign Rock
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
poke
select face where "normal.z > 0.5"
subdivide --cuts 6
# a gently uneven top, flat where the forge and the trip-hammer stand, the rim edge kept
select vert where "pos.z > -0.01 && sqrt(pos.x*pos.x + pos.y*pos.y) < {R*0.93:.2f} && !({FORGE_AREA})"
randomize --amount 0.05 --seed 4
select face where "normal.z > 0.5 && sqrt((pos.x - {POOL[0]})*(pos.x - {POOL[0]}) + (pos.y - ({POOL[1]}))*(pos.y - ({POOL[1]}))) < 0.8"
select face where "normal.z > 0.5 && {seg_expr(POOL, RIM, 0.2)}" --extend
material assign Lava
translate 0 0 -0.12
"""]
for i, pl in enumerate(CRACKS):
    ex = " || ".join(seg_expr(pl[k], pl[k + 1], 0.17) for k in range(len(pl) - 1))
    isl.append(f'select face where "normal.z > 0.5 && material == 0 && ({ex})"\nmaterial assign Crack\ntranslate 0 0 -0.03\n')
isl.append(f"""mode object
add mesh cone --name Under --vertices 11 --radius1 0.6 --radius2 {R - 0.05} --depth 3.0 --location 0 0 -2.0
material assign Rock
active Under
mode edit
select face where "normal.z > 0.9"
delete only-faces
select vert where "pos.z < 1.4"
randomize --amount 0.3 --seed 9
# a few glowing seams on the underside too
select face where "pos.z < 0.8 && pos.z > -0.6 && (index % 5 == 0)"
material assign Crack
mode object
select all
shade flat
export island.glb
""")
open("island.txt", "w").write("".join(isl))

# ---- lava fall: local frame, the cliff face is the plane x = 0 (island inside at x < 0), the fall
# runs down along -Z, slanting out (+X) 0.5 m over its 6 m. A static sheet (magenta) and salmon globs
# in N stacked copies of one H-tall field; the object moves one copy spacing per loop (down H, out
# SLANT*H + E), so each copy takes the next one's place: seamless. Copy c sits E*c further out than the
# sheet: the top copies are inside the 0.2 m thick sheet (hidden), so globs emerge from the lava and
# peel away from it as they fall; the lowest copy leaves the bottom of the frame.
random.seed(11)
H, N, LOOP_FRAMES = 0.6, 10, 12        # 0.6 m per 1 s
LEN, SLANT, E = 6.0, 0.5 / 6.0, 0.03
globs = [(random.uniform(0.0, H), random.uniform(-0.2, 0.2)) for _ in range(4)]
lf = [f"""# Lava fall over the rim: a 0.2 m thick sheet hugging the cliff, running {LEN:.0f} m down into the void and
# slanting 0.5 m out, and salmon globs falling along it in a seamless loop: {N} identical {H} m fields
# stacked along the stream, copy c set {E} m * c further out than the sheet (the top copies are hidden
# inside it, so globs emerge from the lava and peel away as they fall); the stream moves one copy per
# {LOOP_FRAMES / 12:.0f} s. Local frame: the cliff face is x = 0, island inside at x < 0. Generated by make_env.py.
new
fps 12
frame range 0 {LOOP_FRAMES}
material new Fall {col('magenta', True)} --no-slot
material new Glob {col('salmon', True)} --no-slot
add mesh cube --name Lip --size 1 --location -0.15 0 -0.04
scale 0.5 0.7 0.12
apply --scale
material assign Fall
add mesh cube --name Sheet --size 1 --location 0.06 0 {-LEN / 2}
scale 0.2 0.62 {LEN}
apply --scale
material assign Fall
active Sheet
mode edit
select vert where "pos.z < -1"
translate 0.5 0 0
mode object
"""]
names = []
for c in range(N):
    for g, (dz, dy) in enumerate(globs):
        z = 0.1 - (c * H + dz)
        x = 0.06 + SLANT * (-z) + E * c
        n = f"G{c}_{g}"
        names.append(n)
        lf.append(f"add mesh cube --name {n} --size 0.14 --location {x:.3f} {dy:.3f} {z:.3f}\n")
lf.append("select " + " ".join(names) + "\nactive G0_0\njoin\nrename G0_0 Globs\nmaterial assign Glob\n")
lf.append(f"""cursor set 0 0 0
origin set --to cursor
set location 0 0 0
keyframe insert --channels loc --frame 0
set location {SLANT * H + E:.4f} 0 {-H}
keyframe insert --channels loc --frame {LOOP_FRAMES}
keyframe interpolation linear --all
frame set 0
select all
shade flat
export lavafall.glb --bake-animations
""")
open("lavafall.txt", "w").write("".join(lf))

# ---- embers: rising out of the lava pool in N stacked copies of one H-tall field; the object rises
# H and turns ALPHA about the pool's axis per loop, and copy k is copy 0 raised k*H and turned k*ALPHA,
# so each copy takes the next one's place (seamless) and the column does not repeat visibly (a helix
# at the golden angle). The lowest copy starts under the pool surface, inside the island's solid rock;
# the top copy leaves the frame above 6 m.
random.seed(5)
H2, N2, LOOP2, ALPHA = 1.0, 8, 18, 137.5     # 1 m and 137.5 degrees per 1.5 s
pts = []
while len(pts) < 4:
    x, y = random.uniform(-0.6, 0.6), random.uniform(-0.6, 0.6)
    if x * x + y * y < 0.36:
        pts.append((x, y, random.uniform(0, H2)))
em = [f"""# Embers rising from the lava pool: {N2} copies of one {H2:.0f} m field of {len(pts)} embers, copy k raised k m and
# turned k x {ALPHA} degrees; the object rises {H2:.0f} m and turns {ALPHA} degrees per {LOOP2 / 12} s, so each copy
# takes the next one's place (seamless, and a golden-angle helix does not read as a repeat). The lowest
# copy starts under the pool surface, inside the island's rock; the top one leaves the frame. Pool
# centre at the origin. Generated by make_env.py.
new
fps 12
frame range 0 {LOOP2}
material new Ember {col('salmon', True)} --no-slot
"""]
names = []
for k in range(N2):
    a = math.radians(ALPHA * k)
    ca, sa = math.cos(a), math.sin(a)
    for i, (x, y, z) in enumerate(pts):
        n = f"E{i}_{k}"; names.append(n)
        em.append(f"add mesh cube --name {n} --size 0.09 --location {x * ca - y * sa:.3f} {x * sa + y * ca:.3f} {z + H2 * (k - 1):.3f}\n")
em.append("select " + " ".join(names) + f"""
active E0_0
join
rename E0_0 Embers
material assign Ember
cursor set 0 0 0
origin set --to cursor
set location 0 0 0
set rotation 0 0 0
keyframe insert --channels loc,rot --frame 0
set location 0 0 {H2}
set rotation 0 0 {ALPHA}
keyframe insert --channels loc,rot --frame {LOOP2}
keyframe interpolation linear --all
frame set 0
export embers.glb --bake-animations
""")
open("embers.txt", "w").write("".join(em))

# ---- lava blobs bobbing in the pool: four rigid blobs, each its own object (one bone each), a 2 s
# bob each with its own offset; the low pose is under the pool surface (z -0.12 in the scene)
bl = ["""# Lava blobs bobbing in the pool: four crusted blobs (one bone each), each rises out of the lava and
# sinks back in a 2 s loop, offset by a quarter loop from the next. Pool centre at the origin; its
# surface is 0.12 below the island top. Generated by make_env.py.
new
fps 12
frame range 0 24
material new Blob """ + col('magenta', True) + " --no-slot\n"]
spots = [(0.25, 0.15, 0.16), (-0.3, 0.2, 0.13), (0.05, -0.35, 0.14), (-0.2, -0.1, 0.11)]
for i, (x, y, r) in enumerate(spots):
    bl.append(f"""add mesh ico-sphere --name Blob{i} --subdivisions 1 --radius {r} --location {x} {y} -0.12
scale 1 1 0.8
apply --scale
material assign Blob
""")
for i, (x, y, r) in enumerate(spots):
    o = i * 6
    # one cycle: up at 6, down at 12, rest until 24; shifted by o and wrapped, keyed every 6 frames
    cyc = {(f + o) % 24: z for f, z in [(0, -0.30), (6, -0.06), (12, -0.30), (18, -0.30)]}
    bl.append(f"select Blob{i}\n")
    for f in range(0, 25, 6):
        z = cyc[f % 24]
        bl.append(f"frame set {f}\nset location {x} {y} {z:.2f}\nkeyframe insert --channels loc\n")
bl.append("frame set 0\nselect all\nshade flat\nexport blobs.glb --bake-animations\n")
open("blobs.txt", "w").write("".join(bl))
print("wrote island.txt lavafall.txt embers.txt blobs.txt")
